const DB_NAME="crowspace-caws",STORE="videos";let db,videoBlob=null,thumbBlob=null,duration=0,editingId=null,currentTab="all",allItems=[],selected=new Set();
const $=id=>document.getElementById(id);
function initDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,2);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE,{keyPath:"id"});document.querySelectorAll(".season-edit").forEach(b=>b.onclick=async()=>{const season=Number(b.dataset.season);const title=prompt("Season label (optional):",`Season ${season}`);if(title===null)return;await updateSeriesMeta(series,season,{seasonLabel:title.trim()||`Season ${season}`});allItems=await getAll();refresh()});document.querySelectorAll("[data-move]").forEach(b=>b.onclick=async()=>{await moveEpisode(b.dataset.id,Number(b.dataset.move));allItems=await getAll();refresh()})};r.onsuccess=()=>{db=r.result;resolve()};r.onerror=()=>reject(r.error)})}
function all(){return new Promise((res,rej)=>{const r=db.transaction(STORE,"readonly").objectStore(STORE).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function save(item){return new Promise((res,rej)=>{const t=db.transaction(STORE,"readwrite");t.objectStore(STORE).save(item);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
function remove(id){return new Promise((res,rej)=>{const t=db.transaction(STORE,"readwrite");t.objectStore(STORE).delete(id);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
function format(s){return isFinite(s)?Math.floor(s/60)+":"+String(Math.floor(s%60)).padStart(2,"0"):"—"}
function esc(s){return String(s||"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function loadVideo(file){if(!file||!file.type.startsWith("video/"))return;videoBlob=file;$("fileName").textContent=file.name;$("uploadState").textContent="Video selected";const v=$("previewVideo");v.src=URL.createObjectURL(file);v.onloadedmetadata=()=>{duration=v.duration;$("durationLabel").textContent="Duration: "+format(duration);$("thumbTime").max=duration;$("thumbTime").value=Math.min(1,duration);drawThumb()}}
$("videoFile").onchange=e=>loadVideo(e.target.files[0]);
$("previewVideo").ontimeupdate=drawThumb;$("thumbTime").oninput=()=>{$("previewVideo").currentTime=+$("thumbTime").value;drawThumb()};
function drawThumb(){const v=$("previewVideo"),c=$("thumbCanvas"),x=c.getContext("2d");if(!v.videoWidth)return;const ratio=Math.max(c.width/v.videoWidth,c.height/v.videoHeight),w=v.videoWidth*ratio,h=v.videoHeight*ratio;x.fillStyle="#05070c";x.fillRect(0,0,c.width,c.height);x.drawImage(v,(c.width-w)/2,(c.height-h)/2,w,h);c.toBlob(b=>thumbBlob=b,"image/jpeg",.82)}
$("dropZone").ondragover=e=>{e.preventDefault();$("dropZone").classList.add("drag")};$("dropZone").ondragleave=()=>$("dropZone").classList.remove("drag");$("dropZone").ondrop=e=>{e.preventDefault();$("dropZone").classList.remove("drag");loadVideo(e.dataTransfer.files[0])};
function openEditor(item=null){editingId=item?.id||null;$("editorTitle").textContent=item?"Edit your Caw":"Create your Caw";$("creatorName").value=item?.creator||"Jonathan Riehle";$("creatorHandle").value=item?.handle||"@jriehle";$("caption").value=item?.caption||"";$("cawCategory").value=item?.category||"General";$("cawSeries").value=item?.series||"";$("cawEpisode").value=item?.episode||"";$("cawSeason").value=item?.season||1;$("cawTags").value=(item?.tags||[]).join(", ");$("scheduleAt").value=item?.scheduledAt||"";videoBlob=item?.video||null;thumbBlob=item?.thumb||null;duration=item?.duration||0;$("fileName").textContent=item?.fileName||"No video selected";$("durationLabel").textContent="Duration: "+format(duration);$("uploadState").textContent=item?"Editing saved Caw":"Ready";if(item?.video){$("previewVideo").src=URL.createObjectURL(item.video);$("previewVideo").onloadedmetadata=()=>{duration=$("previewVideo").duration;$("thumbTime").max=duration;drawThumb()}}else{$("previewVideo").removeAttribute("src");$("previewVideo").load();$("thumbCanvas").getContext("2d").clearRect(0,0,360,640)}$("studioStatus").textContent="";$("editorModal").classList.add("show")}
function closeEditor(){$("editorModal").classList.remove("show");editingId=null;videoBlob=null;thumbBlob=null}
$("createCaw").onclick=()=>openEditor();$("closeEditor").onclick=closeEditor;
async function stageUpload(){if(!videoBlob)return;const size=videoBlob.size||0;let loaded=0;const chunk=Math.max(262144,Math.ceil(size/20));$("uploadState").textContent="Preparing 0%";while(loaded<size){const end=Math.min(size,loaded+chunk);await videoBlob.slice(loaded,end).arrayBuffer();loaded=end;$("uploadState").textContent="Preparing "+Math.round(loaded/size*100)+"%";await new Promise(r=>setTimeout(r,0))}$("uploadState").textContent="Ready";}
async function persist(status){const scheduledAt=$("scheduleAt").value;if(status==="published"&&scheduledAt&&new Date(scheduledAt)>new Date())status="scheduled";const name=$("creatorName").value.trim()||"Crow Creator",handle=$("creatorHandle").value.trim()||"@creator",caption=$("caption").value.trim();if(!videoBlob){$("studioStatus").textContent="Select a video first.";return}if(status==="published"&&!caption){$("studioStatus").textContent="Add a caption before publishing.";return}const old=editingId?allItems.find(x=>x.id===editingId):null;const category=$("cawCategory").value||"General",series=$("cawSeries").value.trim();let episode=Math.max(0,parseInt($("cawEpisode").value||"0",10)||0);let season=Math.max(1,parseInt($("cawSeason").value||"1",10)||1);if(series&&!episode){episode=allItems.filter(x=>(x.series||"").trim()===series).reduce((n,x)=>Math.max(n,Number(x.episode)||0),0)+1}const tags=$("cawTags").value.split(",").map(x=>x.trim().replace(/^#/,"")).filter(Boolean).slice(0,10);const item={id:editingId||Date.now(),creator:name,handle,avatar:name.split(/\s+/).map(x=>x[0]).join("").slice(0,2).toUpperCase(),caption,category,series,season,episode,tags,likes:old?.likes||0,comments:old?.comments||0,recasts:old?.recasts||0,duration,video:videoBlob,thumb:thumbBlob||old?.thumb||null,created:old?.created||new Date().toISOString(),status:status,publishedAt:status==="published"?(old?.publishedAt||new Date().toISOString()):old?.publishedAt||"",scheduledAt:scheduledAt||"",fileName:videoBlob.name||old?.fileName||"Caw video"};try{await stageUpload();$("uploadState").textContent=status==="published"?"Publishing…":"Saving draft…";await save(item);$("studioStatus").textContent=status==="published"?"CAW PUBLISHED • Your Caw is ready.":status==="scheduled"?"CAW SCHEDULED • This browser will publish it when Creator Studio is open.":"DRAFT SAVED • You can finish it later.";setTimeout(()=>{closeEditor();refresh()},500)}catch(e){$("studioStatus").textContent="Could not save this Caw in this browser."}}
$("publishCaw").onclick=()=>persist("published");$("saveDraft").onclick=()=>persist("draft");
async function processSchedules(){const now=new Date();let changed=false;for(const x of allItems){if(x.status==="scheduled"&&x.scheduledAt&&new Date(x.scheduledAt)<=now){await save({...x,status:"published",publishedAt:x.publishedAt||new Date().toISOString(),scheduledAt:""});changed=true}}if(changed)await refresh()}
async function quickStatus(id,status){const x=allItems.find(v=>v.id===id);if(!x)return;if(status==="published"&&!String(x.caption||"").trim()){alert("Add a caption before publishing.");return}await save({...x,status,publishedAt:status==="published"?(x.publishedAt||new Date().toISOString()):x.publishedAt||""});await refresh()}
async function duplicateCaw(id){const x=allItems.find(v=>v.id===id);if(!x)return;const copy={...x,id:Date.now()+Math.floor(Math.random()*999),caption:x.caption+" (Copy)",status:"draft",views:0,likes:0,comments:0,recasts:0,created:new Date().toISOString()};await save(copy);await refresh()}
function showAnalytics(x){const ev=Array.isArray(x.analyticsEvents)?x.analyticsEvents:[],now=Date.now(),d7=ev.filter(e=>now-new Date(e.at).getTime()<=6048e5),d30=ev.filter(e=>now-new Date(e.at).getTime()<=2592e6),count=t=>ev.filter(e=>e.type===t).length;$("analyticsTitle").textContent=x.caption||"Untitled Caw";$("analyticsViews").textContent=x.views||0;$("analyticsLikes").textContent=x.likes||0;$("analyticsComments").textContent=x.comments||0;$("analyticsRecaws").textContent=x.recasts||0;const v=x.views||0,e=v?Math.round(((x.likes||0)+(x.comments||0)+(x.recasts||0))/v*100):0;$("analyticsSummary").innerHTML=`<strong>${x.status==="published"?"Published":"Draft"}</strong> • ${e}% interaction rate • Created ${new Date(x.created).toLocaleString()}<br><span class="analytics-period">Last 7 days: ${d7.length} events • Last 30 days: ${d30.length} events • Event history: ${ev.length}</span>`;$("analyticsModal").classList.add("show")}
function card(x){const thumb=x.thumb?URL.createObjectURL(x.thumb):"";return `<article class="studio-item card"><div class="studio-select"><input type="checkbox" data-select-id="${x.id}" ${selected.has(x.id)?"checked":""} aria-label="Select Caw"></div><div class="studio-thumb">${thumb?`<img src="${thumb}" alt="">`:"<span>CAW</span>"}<i>${format(x.duration)}</i></div><div class="studio-item-body"><div class="studio-item-head"><div><b>${esc(x.creator)}</b><small>${esc(x.handle)}</small></div><span class="status-pill ${x.status}">${x.status==="published"?"PUBLISHED":x.status==="scheduled"?"SCHEDULED":"DRAFT"}</span></div><p>${x.series?`<span class="caw-series">${esc(x.series)}${x.episode?` • EP ${x.episode}`:""}</span> `:""}${esc(x.caption)}</p><div class="caw-taxonomy"><span>${esc(x.category||"General")}</span>${(x.tags||[]).map(t=>`<i>#${esc(t)}</i>`).join("")}</div><div class="metric-row"><span>◉ ${x.views||0} views</span><span>♥ ${x.likes||0}</span><span>💬 ${x.comments||0}</span><span>↻ ${x.recasts||0}</span></div><div class="item-actions"><button data-act="edit" data-id="${x.id}">Edit</button><button data-act="duplicate" data-id="${x.id}">Duplicate</button>${x.status==="draft"?`<button data-act="publish" data-id="${x.id}">Publish</button>`:`<button data-act="unpublish" data-id="${x.id}">Unpublish</button>`}<button data-act="analytics" data-id="${x.id}">Analytics</button><button data-act="view" data-id="${x.id}">View</button><button class="danger" data-act="delete" data-id="${x.id}">Delete</button></div></div></article>`}
async function refresh(){allItems=(await all()).sort((a,b)=>new Date(b.created)-new Date(a.created));$("totalCount").textContent=allItems.length;$("publishedCount").textContent=allItems.filter(x=>x.status==="published").length;$("draftCount").textContent=allItems.filter(x=>x.status==="draft").length;const views=allItems.reduce((n,x)=>n+(x.views||0),0),engagement=views?Math.round((allItems.reduce((n,x)=>n+(x.likes||0)+(x.comments||0)+(x.recasts||0),0)/views)*100):0;$("totalViews").textContent=views;$("totalEngagement").textContent=engagement+"%";$("insightViews").textContent=views;$("insightText").textContent=allItems.length?`Across ${allItems.length} local Caw${allItems.length===1?"":"s"} • ${engagement}% interaction rate`:"Publish a Caw to begin building your local analytics.";refreshSeriesFilter();renderSeriesHub();const selectedSeries=$("studioSeries")?.value||"all";renderSeriesOverview(selectedSeries);renderSeriesHealth(selectedSeries);renderSeriesNextAction(selectedSeries);renderSeriesProgression(selectedSeries);renderSeriesProductionFlow(selectedSeries);renderSeriesMilestoneTracker(selectedSeries);renderSeriesProductionGaps(selectedSeries);renderSeriesReleaseQueue(selectedSeries);renderSeriesAssetHealth(selectedSeries);renderSeriesVelocity(selectedSeries);renderSeriesConsistency(selectedSeries);renderSeriesCompletion(selectedSeries);renderSeriesNextRelease(selectedSeries);renderSeriesEngagementPulse(selectedSeries);renderSeriesTopEpisode(selectedSeries);renderSeriesSeasonSpread(selectedSeries);renderSeriesSeasonBalance(selectedSeries);renderSeriesViewDistribution(selectedSeries);renderSeriesAverageRuntime(selectedSeries);renderSeriesCompletionForecast(selectedSeries);renderSeriesStreak(selectedSeries);renderSeriesCadence(selectedSeries);renderSeriesActivityCalendar(selectedSeries);renderSeriesReleasePattern(selectedSeries);renderLibrary();renderSeriesTimeline();renderCalendar();processSchedules()}
function renderSeriesActivityCalendar(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published"&&[x.createdAt,x.updatedAt,x.created].some(v=>v&&Number.isFinite(new Date(v).getTime())));const counts={};items.forEach(x=>{const d=new Date(x.createdAt||x.updatedAt||x.created);const k=d.toISOString().slice(0,10);counts[k]=(counts[k]||0)+1});const today=new Date();const cells=[];for(let i=29;i>=0;i--){const d=new Date(today);d.setDate(d.getDate()-i);const k=d.toISOString().slice(0,10),n=counts[k]||0;cells.push('<span title="'+k+' • '+n+' published">'+(n?'●':'·')+'</span>')}el.insertAdjacentHTML("afterbegin",'<div class="series-activity-calendar"><b>30-DAY RELEASE ACTIVITY</b><div>'+cells.join("")+'</div><small>'+items.length+' dated published episode'+(items.length===1?'':'s')+' in available history</small></div>')}
function renderSeriesReleasePattern(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published");const byDay=[0,0,0,0,0,0,0],byWeek={};items.forEach(x=>{const d=new Date(x.createdAt||x.updatedAt||x.created||Date.now());byDay[d.getDay()]++;const monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));const key=monday.toISOString().slice(0,10);byWeek[key]=(byWeek[key]||0)+1});const names=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"],max=Math.max(1,...byDay);const days=names.map((n,i)=>'<span><b>'+n+'</b><i style="width:'+Math.round(byDay[i]/max*100)+'%"></i><small>'+byDay[i]+'</small></span>').join("");const weeks=Object.entries(byWeek).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,4).map(([k,n])=>'<em>'+k+' • '+n+' published</em>').join("");el.insertAdjacentHTML("afterbegin",'<div class="series-release-pattern"><b>RELEASE PATTERN</b><div class="pattern-days">'+days+'</div><div class="pattern-weeks">'+(weeks||"No weekly release history yet.")+'</div></div>')}
function renderSeriesStreak(series){const el=$("seriesBar");if(!el||series==="all")return;const dates=[...new Set(allItems.filter(x=>(x.series||"")===series&&x.status==="published").map(x=>new Date(x.createdAt||x.updatedAt||Date.now()).toISOString().slice(0,10)))].sort();let streak=0;const today=new Date();for(let i=0;i<365;i++){const d=new Date(today);d.setDate(d.getDate()-i);const k=d.toISOString().slice(0,10);if(dates.includes(k))streak++;else break}el.insertAdjacentHTML("afterbegin",'<div class="series-streak"><b>PUBLISHING STREAK</b><span>'+streak+' consecutive day'+(streak===1?"":"s")+' with a published episode</span></div>')}
function renderSeriesCompletionForecast(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),total=items.length,pub=items.filter(x=>x.status==="published").length,remaining=Math.max(0,total-pub);const dates=items.filter(x=>x.status==="published").map(x=>new Date(x.createdAt||x.updatedAt||Date.now())).sort((a,b)=>a-b);let rate=0;if(dates.length>1){const span=Math.max(1,(dates[dates.length-1]-dates[0])/86400000);rate=dates.length/span}const eta=rate>0&&remaining>0?Math.ceil(remaining/rate):0;el.insertAdjacentHTML("afterbegin",'<div class="series-completion-forecast"><b>COMPLETION FORECAST</b><span>'+(remaining?remaining+' episodes remaining'+(eta?' • estimated '+eta+' active days at current release pace':""):"All current episodes are published")+'</span></div>')}
function renderSeriesAverageRuntime(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published"),secs=items.reduce((n,x)=>n+(Number(x.duration)||0),0),avg=items.length?Math.round(secs/items.length):0;const fmt=s=>{const m=Math.floor(s/60),r=s%60;return m+':'+String(r).padStart(2,'0')};el.insertAdjacentHTML("afterbegin",'<div class="series-average-runtime"><b>SERIES RUNTIME</b><span>'+fmt(secs)+' total • '+fmt(avg)+' average per published episode • '+items.length+' published</span></div>')}
function renderSeriesViewDistribution(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published"),seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b),total=items.reduce((n,x)=>n+(Number(x.viewCount)||0),0);const rows=seasons.map(s=>{const v=items.filter(x=>(Number(x.season)||1)===s).reduce((n,x)=>n+(Number(x.viewCount)||0),0),pct=total?Math.round(v/total*100):0;return '<span>S'+s+' <strong>'+v.toLocaleString()+'</strong> ('+pct+'%)</span>'});el.insertAdjacentHTML("afterbegin",'<div class="series-view-distribution"><b>VIEW DISTRIBUTION</b><div>'+rows.join("")+'</div></div>')}
function renderSeriesSeasonBalance(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const rows=seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published"),pct=a.length?Math.round(p.length/a.length*100):0;return '<span>S'+s+' <strong>'+pct+'%</strong></span>'});el.insertAdjacentHTML("afterbegin",'<div class="series-season-balance"><b>SEASON RELEASE BALANCE</b><div>'+rows.join("")+'</div></div>')}
function renderSeriesSeasonSpread(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const rows=seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published"),v=p.reduce((n,x)=>n+(Number(x.viewCount)||0),0);return 'S'+s+' • '+p.length+'/'+a.length+' published • '+v.toLocaleString()+' views'});el.insertAdjacentHTML("afterbegin",'<div class="series-season-spread"><b>SEASON SPREAD</b><span>'+rows.join("  ·  ")+'</span></div>')}
function renderSeriesTopEpisode(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published").sort((a,b)=>(Number(b.viewCount)||0)-(Number(a.viewCount)||0));const x=items[0];el.insertAdjacentHTML("afterbegin",'<div class="series-top-episode"><b>TOP SERIES EPISODE</b><span>'+ (x?'S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+(Number(x.viewCount)||0).toLocaleString()+' views'+(x.title?' • '+escapeHtml(x.title):""):"No published episodes yet.")+'</span></div>')}
function renderSeriesEngagementPulse(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published"),views=items.reduce((n,x)=>n+(Number(x.viewCount)||0),0),likes=items.reduce((n,x)=>n+(Number(x.likes)||0),0),comments=items.reduce((n,x)=>n+(Number(x.comments)||0),0),recaws=items.reduce((n,x)=>n+(Number(x.recasts)||0),0),interactions=likes+comments+recaws,rate=views?((interactions/views)*100).toFixed(1):"0.0";el.insertAdjacentHTML("afterbegin",'<div class="series-engagement-pulse"><b>ENGAGEMENT PULSE</b><span>'+interactions.toLocaleString()+' interactions • '+rate+'% interaction/view rate • '+likes.toLocaleString()+' likes • '+comments.toLocaleString()+' comments • '+recaws.toLocaleString()+' re-caws</span></div>')}
function renderSeriesNextRelease(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status!=="published").sort((a,b)=>(new Date(a.scheduledAt||"9999-12-31")-new Date(b.scheduledAt||"9999-12-31"))||(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));const x=items[0];el.insertAdjacentHTML("afterbegin",'<div class="series-next-release"><b>NEXT SERIES RELEASE</b><span>'+ (x?'S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+(x.status==="scheduled"&&x.scheduledAt?new Date(x.scheduledAt).toLocaleString():String(x.status||"draft").toUpperCase()):"No unreleased episodes in the series queue.")+'</span></div>')}
function renderSeriesCompletion(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),total=items.length,pub=items.filter(x=>x.status==="published").length,ready=items.filter(x=>(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl)&&String(x.caption||"").trim()).length,complete=total>0&&pub===total&&ready===total;el.insertAdjacentHTML("afterbegin",'<div class="series-completion"><b>SERIES COMPLETION</b><span>'+pub+'/'+total+' published • '+ready+'/'+total+' core-ready • '+(complete?"SERIES COMPLETE":"IN PRODUCTION")+'</span></div>')}
function renderSeriesConsistency(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&Number(x.episode)>0);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const lines=seasons.map(s=>{const es=items.filter(x=>(Number(x.season)||1)===s).map(x=>Number(x.episode)).sort((a,b)=>a-b);const unique=[...new Set(es)],dupes=es.length-unique.length,gaps=[];for(let n=1;n<=(unique[unique.length-1]||0);n++)if(!unique.includes(n))gaps.push(n);return 'S'+s+': '+unique.length+' eps'+(gaps.length?' • '+gaps.length+' gaps':'')+(dupes?' • '+dupes+' duplicates':'')});el.insertAdjacentHTML("afterbegin",'<div class="series-consistency"><b>SERIES ORDER CONSISTENCY</b><span>'+lines.join("  ·  ")+'</span></div>')}
function renderSeriesVelocity(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published");const by={};items.forEach(x=>{const d=new Date(x.createdAt||x.updatedAt||Date.now());const key=d.toISOString().slice(0,10);by[key]=(by[key]||0)+1});const days=Object.keys(by).sort().slice(-14),count=days.reduce((n,d)=>n+by[d],0),avg=days.length?(count/days.length).toFixed(1):"0.0";el.insertAdjacentHTML("afterbegin",'<div class="series-velocity"><b>RELEASE VELOCITY</b><span>'+count+' published across the last '+days.length+' active day'+(days.length===1?"":"s")+' • '+avg+' episodes/day</span></div>')}
function renderSeriesAssetHealth(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const checks={video:0,thumb:0,caption:0,creator:0,metadata:0};items.forEach(x=>{if(x.videoUrl||x.videoBlob)checks.video++;if(x.thumbUrl||x.thumbnailUrl)checks.thumb++;if(String(x.caption||"").trim())checks.caption++;if(String(x.creator||"").trim())checks.creator++;if(String(x.category||"").trim()||String(x.series||"").trim()||Number(x.episode)>0)checks.metadata++});const total=items.length;const pct=k=>total?Math.round(checks[k]/total*100):0;el.insertAdjacentHTML("afterbegin",'<div class="series-asset-health"><b>SERIES ASSET HEALTH</b><div>'+["video","thumb","caption","creator","metadata"].map(k=>'<span>'+k.toUpperCase()+' <strong>'+checks[k]+'/'+total+'</strong> '+pct(k)+'%</span>').join("")+'</div></div>')}
function renderSeriesReleaseQueue(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));const queue=items.filter(x=>x.status!=="published").slice(0,8);el.insertAdjacentHTML("afterbegin",'<div class="series-release-queue"><b>SERIES RELEASE QUEUE</b><div>'+(queue.length?queue.map(x=>'<span>S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+(x.status||"draft").toUpperCase()+'</span>').join(""):"<span>All numbered episodes are published.</span>")+'</div></div>')}
function renderSeriesProductionGaps(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const bySeason={};items.forEach(x=>{const s=Math.max(1,parseInt(x.season||1,10)||1);const e=parseInt(x.episode||0,10)||0;if(e) (bySeason[s]||(bySeason[s]=[])).push(e)});const gaps=[];Object.keys(bySeason).sort((a,b)=>a-b).forEach(s=>{const nums=[...new Set(bySeason[s])].sort((a,b)=>a-b);for(let n=1;n<=(nums[nums.length-1]||0);n++)if(!nums.includes(n))gaps.push("S"+s+" • EP "+n)});el.insertAdjacentHTML("afterbegin",'<div class="series-production-gaps"><b>PRODUCTION GAPS</b><span>'+(gaps.length?gaps.slice(0,12).join("  ·  "):"No missing episode numbers detected")+'</span></div>')}
function renderSeriesMilestoneTracker(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),pub=items.filter(x=>x.status==="published"),views=pub.reduce((n,x)=>n+(Number(x.viewCount)||0),0);const milestones=[["FIRST EPISODE",pub.length>=1],["5 EPISODES",pub.length>=5],["10 EPISODES",pub.length>=10],["25 EPISODES",pub.length>=25],["50 EPISODES",pub.length>=50],["10K VIEWS",views>=10000]];el.insertAdjacentHTML("afterbegin",'<div class="series-milestone-tracker"><b>SERIES MILESTONES</b><div>'+milestones.map(m=>'<span class="'+(m[1]?"complete":"pending")+'">'+(m[1]?"●":"○")+' '+m[0]+'</span>').join("")+'</div></div>')}
function renderSeriesProductionFlow(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const counts={draft:0,ready:0,scheduled:0,published:0};items.forEach(x=>{if(x.status==="published")counts.published++;else if(x.status==="scheduled")counts.scheduled++;else if(x.status==="draft"){counts.draft++;if(String(x.caption||"").trim()&&(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl))counts.ready++}});el.insertAdjacentHTML("afterbegin",'<div class="series-production-flow"><b>PRODUCTION FLOW</b><span>Draft '+counts.draft+' → Ready '+counts.ready+' → Scheduled '+counts.scheduled+' → Published '+counts.published+'</span></div>')}
function renderSeriesProgression(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="series-progression"><b>SERIES PROGRESSION</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published").length,percent=a.length?Math.round(p/a.length*100):0;return '<span>S'+s+' <i style="width:'+percent+'%"></i> '+percent+'% released</span>'}).join("")+'</div>')}
function renderSeriesNextAction(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const missing=items.filter(x=>!(x.videoUrl||x.videoBlob)||!(x.thumbUrl||x.thumbnailUrl)||!String(x.caption||"").trim());const drafts=items.filter(x=>x.status==="draft");const scheduled=items.filter(x=>x.status==="scheduled");const action=missing[0]?'Complete S'+(missing[0].season||1)+' • EP '+(missing[0].episode||"—")+' assets':drafts[0]?'Finish S'+(drafts[0].season||1)+' • EP '+(drafts[0].episode||"—")+' draft':scheduled[0]?'Next release: S'+(scheduled[0].season||1)+' • EP '+(scheduled[0].episode||"—"):'Series is fully published';el.insertAdjacentHTML("afterbegin",'<div class="series-next-action"><b>NEXT ACTION</b><span>'+action+'</span></div>')}
function renderSeriesHealth(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),published=items.filter(x=>x.status==="published").length,scheduled=items.filter(x=>x.status==="scheduled").length,drafts=items.filter(x=>x.status==="draft").length,ready=items.filter(x=>String(x.caption||"").trim()&&(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl)).length;const score=items.length?Math.round(((published+ready)/2/items.length)*100):0;el.insertAdjacentHTML("afterbegin",'<div class="series-health"><b>SERIES HEALTH</b><span>'+score+'% production health • '+published+' published • '+scheduled+' scheduled • '+drafts+' drafts • '+ready+'/'+items.length+' ready</span></div>')}
function renderSeriesOverview(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b),pub=items.filter(x=>x.status==="published").length,views=items.reduce((n,x)=>n+(Number(x.viewCount)||0),0),runtime=items.reduce((n,x)=>n+(Number(x.duration)||0),0);const mins=Math.floor(runtime/60),secs=runtime%60;el.insertAdjacentHTML("afterbegin",'<div class="series-overview"><b>SERIES OVERVIEW</b><span>'+items.length+' episodes • '+seasons.length+' seasons • '+pub+' published • '+views.toLocaleString()+' views • '+mins+'m '+secs+'s runtime</span></div>')}
function renderSeriesHub(){const map={};allItems.forEach(x=>{const s=(x.series||"").trim();if(!s)return;if(!map[s])map[s]={count:0,views:0,published:0};map[s].count++;map[s].views+=x.views||0;if(x.status==="published")map[s].published++});const names=Object.keys(map).sort((a,b)=>map[b].count-map[a].count);$("seriesSummary").textContent=names.length?`${names.length} series • ${allItems.length} total Caws`:"No series yet";$("seriesStructure").textContent=names.length?names.map(s=>{const seasons=[...new Set(allItems.filter(x=>(x.series||"").trim()===s).map(x=>Number(x.season)||1))].sort((a,b)=>a-b);return `${s}: ${seasons.length} season${seasons.length===1?"":"s"}`}).join(" • "):"Series → Seasons → Episodes";$("seriesList").innerHTML=names.slice(0,6).map(s=>`<button class="series-card" data-series="${esc(s)}"><b>${esc(s)}</b><span>${map[s].count} Caw${map[s].count===1?"":"s"} • ${map[s].views} views</span></button>`).join("");document.querySelectorAll(".series-card").forEach(b=>b.onclick=()=>{$("studioSeries").value=b.dataset.series;currentTab="all";document.querySelectorAll(".studio-tabs button").forEach(x=>x.classList.toggle("selected",x.dataset.tab==="all"));renderLibrary()})}
function reorderSeason(series,season,orderedIds){const seasonItems=allItems.filter(x=>(x.series||"")===series&&(Number(x.season)||1)===season);orderedIds.forEach((id,index)=>{const x=seasonItems.find(v=>String(v.id)===String(id));if(x)x.episode=index+1});return Promise.all(seasonItems.map(x=>save(x)))}
function renumberSeriesSeason(series,season){const items=allItems.filter(x=>(x.series||"")===series&&(Number(x.season)||1)===season).sort((a,b)=>(Number(a.episode)||9999)-(Number(b.episode)||9999)||String(a.created||"").localeCompare(String(b.created||"")));items.forEach((x,i)=>x.episode=i+1);return Promise.all(items.map(x=>save(x)))}function updateSeriesMeta(series,season,patch){const items=allItems.filter(x=>(x.series||"")===series&&(Number(x.season)||1)===season);return Promise.all(items.map(x=>save({...x,...patch})))}
function moveEpisode(id,direction){const item=allItems.find(x=>String(x.id)===String(id));if(!item||!item.series)return Promise.resolve();const season=Number(item.season)||1;const siblings=allItems.filter(x=>(x.series||"")===item.series&&(Number(x.season)||1)===season).sort((a,b)=>(Number(a.episode)||9999)-(Number(b.episode)||9999));const i=siblings.findIndex(x=>String(x.id)===String(id));const target=siblings[i+direction];if(!target)return Promise.resolve();const e=item.episode||i+1;item.episode=target.episode||i+2;target.episode=e;return Promise.all([save(item),save(target)])}
function getEpisodeStatusSummary(series){const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);return seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published").length,d=a.filter(x=>x.status==="draft").length,sch=a.filter(x=>x.status==="scheduled").length;return {season:s,label:a[0]?.seasonLabel||"Season "+s,total:a.length,published:p,drafts:d,scheduled:sch}})}
function renderSeasonAudience(series){const el=$("seasonCompare");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-audience"><b>SEASON AUDIENCE SNAPSHOT</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),published=a.filter(x=>x.status==="published"),views=published.reduce((n,x)=>n+(Number(x.viewCount)||0),0),avg=published.length?Math.round(views/published.length):0;return '<span>S'+s+' • '+published.length+' published • '+views.toLocaleString()+' total views • '+avg.toLocaleString()+' avg views/episode</span>'}).join("")+'</div>')}
function renderSeasonTopEpisodes(series){const el=$("seasonCompare");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-top-episodes"><b>TOP EPISODES BY VIEWS</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s).sort((p,q)=>(Number(q.viewCount)||0)-(Number(p.viewCount)||0)).slice(0,3);return '<span>S'+s+' • '+(a.length?a.map(x=>'EP '+(x.episode||"—")+' ('+(Number(x.viewCount)||0).toLocaleString()+' views)').join(' • '):'No episodes')+'</span>'}).join("")+'</div>')}
function renderSeasonEngagement(series){const el=$("seasonCompare");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-engagement"><b>SEASON ENGAGEMENT</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s);const views=a.reduce((n,x)=>n+(Number(x.viewCount)||0),0),likes=a.reduce((n,x)=>n+(Number(x.likes)||0),0),comments=a.reduce((n,x)=>n+(Number(x.comments)||0),0),recaws=a.reduce((n,x)=>n+(Number(x.recaws)||0),0),rate=views?((likes+comments+recaws)/views*100).toFixed(1):"0.0";return '<span>S'+s+' • '+views.toLocaleString()+' views • '+likes.toLocaleString()+' likes • '+comments.toLocaleString()+' comments • '+recaws.toLocaleString()+' re-caws • '+rate+'% interaction</span>'}).join("")+'</div>')}
function renderSeasonRuntime(series){const el=$("seasonCompare");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-runtime"><b>SEASON RUNTIME</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s);const secs=a.reduce((n,x)=>n+(Number(x.duration)||0),0);const avg=a.length?Math.round(secs/a.length):0;const fmt=n=>{n=Math.max(0,Math.round(n));const m=Math.floor(n/60),q=n%60;return m+'m '+q+'s'};return '<span>S'+s+' • '+a.length+' episodes • '+fmt(secs)+' total • '+fmt(avg)+' average</span>'}).join("")+'</div>')}
function renderSeasonCompare(series){const el=$("seasonCompare");if(!el)return;if(series==="all"){el.innerHTML="";return}const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.innerHTML=seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),v=a.reduce((n,x)=>n+(Number(x.viewCount)||0),0),l=a.reduce((n,x)=>n+(Number(x.likeCount)||0),0),c=a.reduce((n,x)=>n+(Number(x.commentCount)||0),0);return '<div class="season-compare-row"><b>'+esc(a[0]?.seasonLabel||"Season "+s)+'</b><span>'+a.length+' eps</span><span>'+v.toLocaleString()+' views</span><span>'+l.toLocaleString()+' likes</span><span>'+c.toLocaleString()+' comments</span></div>'}).join("")}
function renderSeasonLaunch(series){const el=$("seasonMilestones");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const now=Date.now();el.insertAdjacentHTML("afterbegin",'<div class="season-launch"><b>NEXT RELEASE</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s&&x.status==="scheduled"&&x.scheduledAt&&new Date(x.scheduledAt).getTime()>now).sort((x,y)=>new Date(x.scheduledAt)-new Date(y.scheduledAt));const x=a[0];return x?'<span>S'+s+' • EP '+(x.episode||"—")+' • '+new Date(x.scheduledAt).toLocaleString()+'</span>':'<span>S'+s+' • No upcoming release scheduled</span>'}).join("")+'</div>')}
function renderSeasonTargets(series){const el=$("seasonMilestones");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-targets"><b>SEASON TARGETS</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published").length;return '<span><strong>S'+s+'</strong> '+p+'/'+a.length+' released</span>'}).join("")+'</div>')}
function renderSeasonOrderHealth(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-order-health"><b>EPISODE ORDER HEALTH</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s).sort((p,q)=>(Number(p.episode)||0)-(Number(q.episode)||0));const nums=a.map(x=>Number(x.episode)).filter(Number.isFinite);const dup=nums.filter((n,i)=>nums.indexOf(n)!==i);const missing=[];for(let n=1;n<=(nums.length?Math.max(...nums):0);n++)if(!nums.includes(n))missing.push(n);const issue=dup.length||missing.length;return '<span>S'+s+' • '+(issue?'CHECK ORDER'+(missing.length?' • Missing '+missing.join(", "):"")+(dup.length?' • Duplicate '+[...new Set(dup)].join(", "):""):'Order OK')+'</span>'}).join("")+'</div>')}
function renderSeasonArchive(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-archive"><b>SEASON ARCHIVE STATUS</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),published=a.filter(x=>x.status==="published").length,total=a.length,views=a.reduce((n,x)=>n+(Number(x.viewCount)||0),0);return '<span>S'+s+' • '+published+'/'+total+' published • '+views.toLocaleString()+' views • '+(total&&published===total?'ARCHIVED':'IN PRODUCTION')+'</span>'}).join("")+'</div>')}
function renderSeriesTimelineStats(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const published=items.filter(x=>x.status==="published"),scheduled=items.filter(x=>x.status==="scheduled"),drafts=items.filter(x=>x.status==="draft");const views=published.reduce((n,x)=>n+(Number(x.viewCount)||0),0),likes=published.reduce((n,x)=>n+(Number(x.likes)||0),0);const avg=published.length?Math.round(views/published.length):0;el.insertAdjacentHTML("afterbegin",'<div class="series-timeline-stats"><b>RELEASE SNAPSHOT</b><span>'+published.length+' live • '+scheduled.length+' scheduled • '+drafts.length+' drafts • '+views.toLocaleString()+' views • '+avg.toLocaleString()+' avg views • '+likes.toLocaleString()+' likes</span></div>')}
function renderSeasonEpisodeMap(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-episode-map"><b>SEASON EPISODE MAP</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s).sort((p,q)=>(Number(p.episode)||0)-(Number(q.episode)||0));return '<span>S'+s+' • '+(a.length?a.map(x=>'EP '+(x.episode||"—")+' '+(x.status==="published"?'●':'○')).join('  '):'No episodes')+'</span>'}).join("")+'</div>')}
function renderSeasonReleaseQueue(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));const queue=items.filter(x=>x.status!=="published").slice(0,8);el.insertAdjacentHTML("afterbegin",'<div class="season-release-queue"><b>RELEASE QUEUE</b>'+(queue.length?queue.map(x=>'<span>S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+(x.status||"draft").toUpperCase()+'</span>').join(""):'<span>No unreleased episodes in the current series.</span>')+'</div>')}
function renderSeasonCompletionChecklist(series){const el=$("seasonMilestones");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-completion-checklist"><b>SEASON COMPLETION CHECKLIST</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),published=a.filter(x=>x.status==="published").length,scheduled=a.filter(x=>x.status==="scheduled").length,ready=a.filter(x=>String(x.caption||"").trim()&&(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl)).length;const checks=[published===a.length&&a.length>0,scheduled===0,ready===a.length];return '<span>S'+s+' • '+(checks.filter(Boolean).length)+'/3 checks complete — '+published+'/'+a.length+' published • '+scheduled+' scheduled • '+ready+'/'+a.length+' ready</span>'}).join("")+'</div>')}
function renderSeasonMilestones(series){const el=$("seasonMilestones");if(!el||series==="all"){if(el)el.innerHTML="";return}const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.innerHTML='<div class="milestone-title">SEASON MILESTONES</div>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published"),views=p.reduce((n,x)=>n+(Number(x.viewCount)||0),0);const milestones=[a.length>=1?"FIRST EPISODE":null,a.length>=5?"5 EPISODES":null,a.length>=10?"10 EPISODES":null,p.length===a.length&&a.length?"FULL SEASON RELEASED":null,views>=1000?"1K VIEWS":null].filter(Boolean);return '<div class="milestone-season"><b>'+esc(a[0]?.seasonLabel||"Season "+s)+'</b><div>'+milestones.map(m=>'<span>✓ '+m+'</span>').join("")+'</div></div>'}).join("")}
function renderSeasonReadiness(series){const el=$("seasonPlanner");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const out=seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),published=a.filter(x=>x.status==="published").length,scheduled=a.filter(x=>x.status==="scheduled").length,drafts=a.filter(x=>x.status==="draft").length;return {s,total:a.length,published,scheduled,drafts}});el.insertAdjacentHTML("afterbegin",'<div class="readiness-grid">'+out.map(r=>'<div class="readiness-card"><b>S'+r.s+'</b><span>'+r.published+'/'+r.total+' released</span><small>'+r.scheduled+' scheduled • '+r.drafts+' drafts</small></div>').join("")+'</div>')}
function renderProductionGaps(series){const el=$("seasonPlanner");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const gaps=[];seasons.forEach(s=>{const a=items.filter(x=>(Number(x.season)||1)===s);const nums=a.map(x=>Number(x.episode)).filter(Number.isFinite);if(nums.length){for(let n=1;n<=Math.max(...nums);n++)if(!nums.includes(n))gaps.push("S"+s+" EP "+n)}});el.insertAdjacentHTML("afterbegin",'<div class="production-gaps"><b>PRODUCTION GAPS</b><span>'+(gaps.length?gaps.join(" • "):"No episode-number gaps detected")+'</span></div>')}
function renderEpisodeReadiness(series){const el=$("seasonPlanner");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));el.insertAdjacentHTML("afterbegin",'<div class="episode-readiness"><div class="mini-title">EPISODE READINESS</div>'+items.map(x=>{const checks=[["VIDEO",!!(x.videoUrl||x.videoBlob)],["CAPTION",!!String(x.caption||"").trim()],["THUMBNAIL",!!(x.thumbUrl||x.thumbnailUrl)],["CREATOR",!!String(x.creator||"").trim()],["METADATA",!!(x.series&&x.season&&x.episode)]];const missing=checks.filter(c=>!c[1]).map(c=>c[0]);return '<div class="readiness-episode"><b>S'+(x.season||1)+' • EP '+(x.episode||"—")+'</b><span class="'+(missing.length?'needs':'ready')+'">'+(missing.length?'NEEDS '+missing.join(' • '):'READY')+'</span></div>'}).join("")+'</div>')}
function renderSeasonMissingAssets(series){const el=$("seasonPlanner");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));const missing=items.flatMap(x=>{const m=[];if(!(x.videoUrl||x.videoBlob))m.push("VIDEO");if(!(x.thumbUrl||x.thumbnailUrl))m.push("THUMB");if(!String(x.caption||"").trim())m.push("CAPTION");return m.length?[{x,m}]:[]});el.insertAdjacentHTML("afterbegin",'<div class="season-missing-assets"><b>MISSING ASSETS</b>'+(missing.length?missing.map(({x,m})=>'<span>S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+m.join(" • ")+'</span>').join(""):'<span>All episodes have the core assets required for production.</span>')+'</div>')}
function renderSeasonPlanner(series){const el=$("seasonPlanner");if(!el||series==="all"){if(el)el.innerHTML="";return}const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.innerHTML='<div class="planner-title">PRODUCTION PLANNER</div>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s).sort((x,y)=>(Number(x.episode)||9999)-(Number(y.episode)||9999));return '<div class="planner-season"><b>'+esc(a[0]?.seasonLabel||"Season "+s)+'</b>'+a.map(x=>'<div class="planner-episode"><span>EP '+(x.episode||"—")+'</span><em class="'+x.status+'">'+x.status+'</em><small>'+esc(x.caption||"Untitled Caw")+'</small></div>').join("")+'</div>'}).join("")}
function renderSeasonPublishGate(series){const el=$("seasonHealth");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-publish-gate"><b>PUBLISH GATE</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),missing=a.filter(x=>!(x.videoUrl||x.videoBlob)||!(x.thumbUrl||x.thumbnailUrl)||!String(x.caption||"").trim()),drafts=a.filter(x=>x.status==="draft"),scheduled=a.filter(x=>x.status==="scheduled");const ready=a.length>0&&!missing.length&&!drafts.length&&!scheduled.length&&a.every(x=>x.status==="published");return '<span>S'+s+' • '+(ready?'READY TO CLOSE SEASON':'NOT READY')+' — '+(missing.length?'Assets '+missing.length+' • ':'')+(drafts.length?'Drafts '+drafts.length+' • ':'')+(scheduled.length?'Scheduled '+scheduled.length:'')+'</span>'}).join("")+'</div>')}
function renderSeasonHealthBreakdown(series){const el=$("seasonHealth");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="health-breakdown"><b>SEASON HEALTH BREAKDOWN</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s);const published=a.filter(x=>x.status==="published").length,draft=a.filter(x=>x.status==="draft").length,scheduled=a.filter(x=>x.status==="scheduled").length;const ready=a.filter(x=>String(x.caption||"").trim()&&(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl)).length;return '<span>S'+s+' • '+published+' published • '+scheduled+' scheduled • '+draft+' drafts • '+ready+'/'+a.length+' production-ready</span>'}).join("")+'</div>')}
function renderSeasonHealth(series){const el=$("seasonCompare");if(!el||series==="all")return;const rows=getEpisodeStatusSummary(series);el.insertAdjacentHTML("afterbegin",rows.map(r=>{const ready=r.total&&r.published===r.total,attention=r.drafts>0||r.scheduled>0;return '<div class="season-health '+(ready?'ready':'')+'"><b>'+esc(r.label)+'</b><span>'+(ready?'READY • Full season released':attention?(r.scheduled+' scheduled • '+r.drafts+' drafts'):'Needs episodes')+'</span></div>'}).join(""))}
function renderSeasonProgress(series){const el=$("seasonCompare");if(!el||series==="all")return;const rows=getEpisodeStatusSummary(series);el.insertAdjacentHTML("afterbegin",rows.map(r=>{const pct=r.total?Math.round(r.published/r.total*100):0;return '<div class="season-progress"><div><b>'+esc(r.label)+'</b><span>'+pct+'% released</span></div><div class="progress-track"><i style="width:'+pct+'%"></i></div></div>'}).join(""))}
function renderSeasonStats(series){const el=$("timelineTracks");if(series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);$("timelineTitle").textContent=series+" • "+items.length+" episodes";el.insertAdjacentHTML("beforeend",`<div class="season-stats">${seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),v=a.reduce((n,x)=>n+(Number(x.viewCount)||0),0);return `<span><b>${esc(a[0]?.seasonLabel||"Season "+s)}</b> · ${a.length} episodes · ${v.toLocaleString()} views</span>`}).join("")}</div>`)}
function renderSeriesTimeline(){const series=$("studioSeries").value;if(series==="all"){$("timelineTitle").textContent="Select a series";$("timelineTracks").innerHTML="<span class=\"timeline-empty\">Choose a series above to view its episode timeline.</span>";$("renumberSeasonBtn").hidden=true;return}const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||9999)-(Number(b.episode)||9999));$("timelineTitle").textContent=series;const seasons=[...new Set(items.map(x=>Number(x.season)||1))];$("renumberSeasonBtn").hidden=!seasons.length;$("renumberSeasonBtn").onclick=async()=>{const season=Number(prompt("Renumber which season?",String(seasons[0]||1)));if(!Number.isFinite(season)||season<1)return;await renumberSeriesSeason(series,season);allItems=await getAll();refresh()};$("timelineTracks").innerHTML=seasons.map(season=>`<div class="timeline-season"><b>SEASON ${season}</b><button type="button" class="season-edit" data-season="${season}">Edit Season</button><div>${items.filter(x=>(Number(x.season)||1)===season).map(x=>`<div class="timeline-card"><button class="timeline-episode" data-series-id="${x.id}"><strong>EP ${x.episode||"—"}</strong><span>${esc(x.caption||"Untitled Caw")}</span><i class="${x.status}">${x.status}</i></button><div class="timeline-arrows"><button type="button" data-move="-1" data-id="${x.id}">↑</button><button type="button" data-move="1" data-id="${x.id}">↓</button></div></div>`).join("")}</div></div>`).join("");document.querySelectorAll("[data-series-id]").forEach(b=>b.onclick=()=>{const x=allItems.find(v=>String(v.id)===b.dataset.seriesId);if(x)openEditor(x)})}
function renderCalendar(){const list=allItems.filter(x=>x.status==="scheduled"&&x.scheduledAt).sort((a,b)=>new Date(a.scheduledAt)-new Date(b.scheduledAt));const next=list[0];$("nextScheduled").textContent=next?`${esc(next.caption||"Untitled Caw")} • ${new Date(next.scheduledAt).toLocaleString()}`:"No scheduled Caws";$("scheduleList").innerHTML=list.slice(0,6).map(x=>`<div class="schedule-item"><span>${new Date(x.scheduledAt).toLocaleDateString()}</span><b>${esc(x.caption||"Untitled Caw")}</b><small>${new Date(x.scheduledAt).toLocaleTimeString([], {hour:"numeric",minute:"2-digit"})}</small></div>`).join("")}
function updateSelection(){const n=selected.size;$("selectionCount").textContent=n+" selected";$("bulkLabel").textContent=n+" Caw"+(n===1?"":"s")+" selected";$("bulkBar").classList.toggle("show",n>0)}
function refreshSeriesFilter(){const sel=$("studioSeries"),current=sel.value,names=[...new Set(allItems.map(x=>(x.series||"").trim()).filter(Boolean))].sort();sel.innerHTML=`<option value="all">All Series</option>`+names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join("");if(names.includes(current))sel.value=current}
function renderLibrary(){const searchEl=$("studioSearch"),catEl=$("studioCategory"),seriesEl=$("studioSeries"),sortEl=$("studioSort"),libraryEl=$("studioLibrary");if(!searchEl||!catEl||!seriesEl||!sortEl||!libraryEl)return;const q=searchEl.value.trim().toLowerCase(),cat=catEl.value,series=seriesEl.value;let list=allItems.filter(x=>(currentTab==="all"||x.status===currentTab)&&(cat==="all"||(x.category||"General")===cat)&&(series==="all"||(x.series||"")===series));if(q)list=list.filter(x=>(String(x.caption||"")+" "+String(x.creator||"")+" "+String(x.handle||"")).toLowerCase().includes(q));const sort=sortEl.value;if(sort==="views")list.sort((a,b)=>(b.views||0)-(a.views||0));else if(sort==="likes")list.sort((a,b)=>(b.likes||0)-(a.likes||0));else if(sort==="engagement")list.sort((a,b)=>{const er=x=>((x.likes||0)+(x.comments||0)+(x.recasts||0))/Math.max(x.views||0,1);return er(b)-er(a)});libraryEl.innerHTML=list.length?list.map(card).join(""):'<section class="card panel empty-studio"><div class="panel-title">NOTHING HERE YET</div><h3>Create your first Caw.</h3><p>Your drafts and published Caws will appear here.</p><button class="post-button" type="button" data-create-empty>＋ Create Caw</button></section>';document.querySelectorAll("[data-select-id]").forEach(cb=>cb.onchange=()=>{const id=Number(cb.dataset.selectId);cb.checked?selected.add(id):selected.delete(id);updateSelection()});document.querySelectorAll(".studio-item button").forEach(b=>b.onclick=async()=>{const x=allItems.find(v=>String(v.id)===b.dataset.id);if(!x)return;const act=b.dataset.act;if(act==="edit")openEditor(x);else if(act==="duplicate")await duplicateCaw(x.id);else if(act==="publish")await quickStatus(x.id,"published");else if(act==="unpublish")await quickStatus(x.id,"draft");else if(act==="analytics")showAnalytics(x);else if(act==="view"){localStorage.setItem("crowspace:cawFocus",String(x.id));location.href="caws.html#caw-"+x.id}else if(act==="delete"&&confirm("Delete this Caw?")){await remove(x.id);await refresh()}});const empty=document.querySelector("[data-create-empty]");if(empty)empty.addEventListener("click",()=>openEditor())}
function renderSeriesStreak(series){const el=$("seriesBar");if(!el||series==="all")return;const dates=[...new Set(allItems.filter(x=>(x.series||"")===series&&x.status==="published").map(x=>new Date(x.createdAt||x.updatedAt||Date.now()).toISOString().slice(0,10)))].sort();let streak=0;const today=new Date();for(let i=0;i<365;i++){const d=new Date(today);d.setDate(d.getDate()-i);const k=d.toISOString().slice(0,10);if(dates.includes(k))streak++;else break}el.insertAdjacentHTML("afterbegin",'<div class="series-streak"><b>PUBLISHING STREAK</b><span>'+streak+' consecutive day'+(streak===1?"":"s")+' with a published episode</span></div>')}
function renderSeriesCompletionForecast(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),total=items.length,pub=items.filter(x=>x.status==="published").length,remaining=Math.max(0,total-pub);const dates=items.filter(x=>x.status==="published").map(x=>new Date(x.createdAt||x.updatedAt||Date.now())).sort((a,b)=>a-b);let rate=0;if(dates.length>1){const span=Math.max(1,(dates[dates.length-1]-dates[0])/86400000);rate=dates.length/span}const eta=rate>0&&remaining>0?Math.ceil(remaining/rate):0;el.insertAdjacentHTML("afterbegin",'<div class="series-completion-forecast"><b>COMPLETION FORECAST</b><span>'+(remaining?remaining+' episodes remaining'+(eta?' • estimated '+eta+' active days at current release pace':""):"All current episodes are published")+'</span></div>')}
function renderSeriesAverageRuntime(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published"),secs=items.reduce((n,x)=>n+(Number(x.duration)||0),0),avg=items.length?Math.round(secs/items.length):0;const fmt=s=>{const m=Math.floor(s/60),r=s%60;return m+':'+String(r).padStart(2,'0')};el.insertAdjacentHTML("afterbegin",'<div class="series-average-runtime"><b>SERIES RUNTIME</b><span>'+fmt(secs)+' total • '+fmt(avg)+' average per published episode • '+items.length+' published</span></div>')}
function renderSeriesViewDistribution(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published"),seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b),total=items.reduce((n,x)=>n+(Number(x.viewCount)||0),0);const rows=seasons.map(s=>{const v=items.filter(x=>(Number(x.season)||1)===s).reduce((n,x)=>n+(Number(x.viewCount)||0),0),pct=total?Math.round(v/total*100):0;return '<span>S'+s+' <strong>'+v.toLocaleString()+'</strong> ('+pct+'%)</span>'});el.insertAdjacentHTML("afterbegin",'<div class="series-view-distribution"><b>VIEW DISTRIBUTION</b><div>'+rows.join("")+'</div></div>')}
function renderSeriesSeasonBalance(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const rows=seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published"),pct=a.length?Math.round(p.length/a.length*100):0;return '<span>S'+s+' <strong>'+pct+'%</strong></span>'});el.insertAdjacentHTML("afterbegin",'<div class="series-season-balance"><b>SEASON RELEASE BALANCE</b><div>'+rows.join("")+'</div></div>')}
function renderSeriesSeasonSpread(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const rows=seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published"),v=p.reduce((n,x)=>n+(Number(x.viewCount)||0),0);return 'S'+s+' • '+p.length+'/'+a.length+' published • '+v.toLocaleString()+' views'});el.insertAdjacentHTML("afterbegin",'<div class="series-season-spread"><b>SEASON SPREAD</b><span>'+rows.join("  ·  ")+'</span></div>')}
function renderSeriesTopEpisode(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published").sort((a,b)=>(Number(b.viewCount)||0)-(Number(a.viewCount)||0));const x=items[0];el.insertAdjacentHTML("afterbegin",'<div class="series-top-episode"><b>TOP SERIES EPISODE</b><span>'+ (x?'S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+(Number(x.viewCount)||0).toLocaleString()+' views'+(x.title?' • '+escapeHtml(x.title):""):"No published episodes yet.")+'</span></div>')}
function renderSeriesEngagementPulse(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published"),views=items.reduce((n,x)=>n+(Number(x.viewCount)||0),0),likes=items.reduce((n,x)=>n+(Number(x.likes)||0),0),comments=items.reduce((n,x)=>n+(Number(x.comments)||0),0),recaws=items.reduce((n,x)=>n+(Number(x.recasts)||0),0),interactions=likes+comments+recaws,rate=views?((interactions/views)*100).toFixed(1):"0.0";el.insertAdjacentHTML("afterbegin",'<div class="series-engagement-pulse"><b>ENGAGEMENT PULSE</b><span>'+interactions.toLocaleString()+' interactions • '+rate+'% interaction/view rate • '+likes.toLocaleString()+' likes • '+comments.toLocaleString()+' comments • '+recaws.toLocaleString()+' re-caws</span></div>')}
function renderSeriesNextRelease(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status!=="published").sort((a,b)=>(new Date(a.scheduledAt||"9999-12-31")-new Date(b.scheduledAt||"9999-12-31"))||(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));const x=items[0];el.insertAdjacentHTML("afterbegin",'<div class="series-next-release"><b>NEXT SERIES RELEASE</b><span>'+ (x?'S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+(x.status==="scheduled"&&x.scheduledAt?new Date(x.scheduledAt).toLocaleString():String(x.status||"draft").toUpperCase()):"No unreleased episodes in the series queue.")+'</span></div>')}
function renderSeriesCompletion(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),total=items.length,pub=items.filter(x=>x.status==="published").length,ready=items.filter(x=>(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl)&&String(x.caption||"").trim()).length,complete=total>0&&pub===total&&ready===total;el.insertAdjacentHTML("afterbegin",'<div class="series-completion"><b>SERIES COMPLETION</b><span>'+pub+'/'+total+' published • '+ready+'/'+total+' core-ready • '+(complete?"SERIES COMPLETE":"IN PRODUCTION")+'</span></div>')}
function renderSeriesConsistency(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&Number(x.episode)>0);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const lines=seasons.map(s=>{const es=items.filter(x=>(Number(x.season)||1)===s).map(x=>Number(x.episode)).sort((a,b)=>a-b);const unique=[...new Set(es)],dupes=es.length-unique.length,gaps=[];for(let n=1;n<=(unique[unique.length-1]||0);n++)if(!unique.includes(n))gaps.push(n);return 'S'+s+': '+unique.length+' eps'+(gaps.length?' • '+gaps.length+' gaps':'')+(dupes?' • '+dupes+' duplicates':'')});el.insertAdjacentHTML("afterbegin",'<div class="series-consistency"><b>SERIES ORDER CONSISTENCY</b><span>'+lines.join("  ·  ")+'</span></div>')}
function renderSeriesVelocity(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series&&x.status==="published");const by={};items.forEach(x=>{const d=new Date(x.createdAt||x.updatedAt||Date.now());const key=d.toISOString().slice(0,10);by[key]=(by[key]||0)+1});const days=Object.keys(by).sort().slice(-14),count=days.reduce((n,d)=>n+by[d],0),avg=days.length?(count/days.length).toFixed(1):"0.0";el.insertAdjacentHTML("afterbegin",'<div class="series-velocity"><b>RELEASE VELOCITY</b><span>'+count+' published across the last '+days.length+' active day'+(days.length===1?"":"s")+' • '+avg+' episodes/day</span></div>')}
function renderSeriesAssetHealth(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const checks={video:0,thumb:0,caption:0,creator:0,metadata:0};items.forEach(x=>{if(x.videoUrl||x.videoBlob)checks.video++;if(x.thumbUrl||x.thumbnailUrl)checks.thumb++;if(String(x.caption||"").trim())checks.caption++;if(String(x.creator||"").trim())checks.creator++;if(String(x.category||"").trim()||String(x.series||"").trim()||Number(x.episode)>0)checks.metadata++});const total=items.length;const pct=k=>total?Math.round(checks[k]/total*100):0;el.insertAdjacentHTML("afterbegin",'<div class="series-asset-health"><b>SERIES ASSET HEALTH</b><div>'+["video","thumb","caption","creator","metadata"].map(k=>'<span>'+k.toUpperCase()+' <strong>'+checks[k]+'/'+total+'</strong> '+pct(k)+'%</span>').join("")+'</div></div>')}
function renderSeriesReleaseQueue(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));const queue=items.filter(x=>x.status!=="published").slice(0,8);el.insertAdjacentHTML("afterbegin",'<div class="series-release-queue"><b>SERIES RELEASE QUEUE</b><div>'+(queue.length?queue.map(x=>'<span>S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+(x.status||"draft").toUpperCase()+'</span>').join(""):"<span>All numbered episodes are published.</span>")+'</div></div>')}
function renderSeriesProductionGaps(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const bySeason={};items.forEach(x=>{const s=Math.max(1,parseInt(x.season||1,10)||1);const e=parseInt(x.episode||0,10)||0;if(e) (bySeason[s]||(bySeason[s]=[])).push(e)});const gaps=[];Object.keys(bySeason).sort((a,b)=>a-b).forEach(s=>{const nums=[...new Set(bySeason[s])].sort((a,b)=>a-b);for(let n=1;n<=(nums[nums.length-1]||0);n++)if(!nums.includes(n))gaps.push("S"+s+" • EP "+n)});el.insertAdjacentHTML("afterbegin",'<div class="series-production-gaps"><b>PRODUCTION GAPS</b><span>'+(gaps.length?gaps.slice(0,12).join("  ·  "):"No missing episode numbers detected")+'</span></div>')}
function renderSeriesMilestoneTracker(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),pub=items.filter(x=>x.status==="published"),views=pub.reduce((n,x)=>n+(Number(x.viewCount)||0),0);const milestones=[["FIRST EPISODE",pub.length>=1],["5 EPISODES",pub.length>=5],["10 EPISODES",pub.length>=10],["25 EPISODES",pub.length>=25],["50 EPISODES",pub.length>=50],["10K VIEWS",views>=10000]];el.insertAdjacentHTML("afterbegin",'<div class="series-milestone-tracker"><b>SERIES MILESTONES</b><div>'+milestones.map(m=>'<span class="'+(m[1]?"complete":"pending")+'">'+(m[1]?"●":"○")+' '+m[0]+'</span>').join("")+'</div></div>')}
function renderSeriesProductionFlow(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const counts={draft:0,ready:0,scheduled:0,published:0};items.forEach(x=>{if(x.status==="published")counts.published++;else if(x.status==="scheduled")counts.scheduled++;else if(x.status==="draft"){counts.draft++;if(String(x.caption||"").trim()&&(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl))counts.ready++}});el.insertAdjacentHTML("afterbegin",'<div class="series-production-flow"><b>PRODUCTION FLOW</b><span>Draft '+counts.draft+' → Ready '+counts.ready+' → Scheduled '+counts.scheduled+' → Published '+counts.published+'</span></div>')}
function renderSeriesProgression(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="series-progression"><b>SERIES PROGRESSION</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published").length,percent=a.length?Math.round(p/a.length*100):0;return '<span>S'+s+' <i style="width:'+percent+'%"></i> '+percent+'% released</span>'}).join("")+'</div>')}
function renderSeriesNextAction(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const missing=items.filter(x=>!(x.videoUrl||x.videoBlob)||!(x.thumbUrl||x.thumbnailUrl)||!String(x.caption||"").trim());const drafts=items.filter(x=>x.status==="draft");const scheduled=items.filter(x=>x.status==="scheduled");const action=missing[0]?'Complete S'+(missing[0].season||1)+' • EP '+(missing[0].episode||"—")+' assets':drafts[0]?'Finish S'+(drafts[0].season||1)+' • EP '+(drafts[0].episode||"—")+' draft':scheduled[0]?'Next release: S'+(scheduled[0].season||1)+' • EP '+(scheduled[0].episode||"—"):'Series is fully published';el.insertAdjacentHTML("afterbegin",'<div class="series-next-action"><b>NEXT ACTION</b><span>'+action+'</span></div>')}
function renderSeriesHealth(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series),published=items.filter(x=>x.status==="published").length,scheduled=items.filter(x=>x.status==="scheduled").length,drafts=items.filter(x=>x.status==="draft").length,ready=items.filter(x=>String(x.caption||"").trim()&&(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl)).length;const score=items.length?Math.round(((published+ready)/2/items.length)*100):0;el.insertAdjacentHTML("afterbegin",'<div class="series-health"><b>SERIES HEALTH</b><span>'+score+'% production health • '+published+' published • '+scheduled+' scheduled • '+drafts+' drafts • '+ready+'/'+items.length+' ready</span></div>')}
function renderSeriesOverview(series){const el=$("seriesBar");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b),pub=items.filter(x=>x.status==="published").length,views=items.reduce((n,x)=>n+(Number(x.viewCount)||0),0),runtime=items.reduce((n,x)=>n+(Number(x.duration)||0),0);const mins=Math.floor(runtime/60),secs=runtime%60;el.insertAdjacentHTML("afterbegin",'<div class="series-overview"><b>SERIES OVERVIEW</b><span>'+items.length+' episodes • '+seasons.length+' seasons • '+pub+' published • '+views.toLocaleString()+' views • '+mins+'m '+secs+'s runtime</span></div>')}
function renderSeriesHub(){const map={};allItems.forEach(x=>{const s=(x.series||"").trim();if(!s)return;if(!map[s])map[s]={count:0,views:0,published:0};map[s].count++;map[s].views+=x.views||0;if(x.status==="published")map[s].published++});const names=Object.keys(map).sort((a,b)=>map[b].count-map[a].count);$("seriesSummary").textContent=names.length?`${names.length} series • ${allItems.length} total Caws`:"No series yet";$("seriesStructure").textContent=names.length?names.map(s=>{const seasons=[...new Set(allItems.filter(x=>(x.series||"").trim()===s).map(x=>Number(x.season)||1))].sort((a,b)=>a-b);return `${s}: ${seasons.length} season${seasons.length===1?"":"s"}`}).join(" • "):"Series → Seasons → Episodes";$("seriesList").innerHTML=names.slice(0,6).map(s=>`<button class="series-card" data-series="${esc(s)}"><b>${esc(s)}</b><span>${map[s].count} Caw${map[s].count===1?"":"s"} • ${map[s].views} views</span></button>`).join("");document.querySelectorAll(".series-card").forEach(b=>b.onclick=()=>{$("studioSeries").value=b.dataset.series;currentTab="all";document.querySelectorAll(".studio-tabs button").forEach(x=>x.classList.toggle("selected",x.dataset.tab==="all"));renderLibrary()})}
function reorderSeason(series,season,orderedIds){const seasonItems=allItems.filter(x=>(x.series||"")===series&&(Number(x.season)||1)===season);orderedIds.forEach((id,index)=>{const x=seasonItems.find(v=>String(v.id)===String(id));if(x)x.episode=index+1});return Promise.all(seasonItems.map(x=>save(x)))}
function renumberSeriesSeason(series,season){const items=allItems.filter(x=>(x.series||"")===series&&(Number(x.season)||1)===season).sort((a,b)=>(Number(a.episode)||9999)-(Number(b.episode)||9999)||String(a.created||"").localeCompare(String(b.created||"")));items.forEach((x,i)=>x.episode=i+1);return Promise.all(items.map(x=>save(x)))}function updateSeriesMeta(series,season,patch){const items=allItems.filter(x=>(x.series||"")===series&&(Number(x.season)||1)===season);return Promise.all(items.map(x=>save({...x,...patch})))}
function moveEpisode(id,direction){const item=allItems.find(x=>String(x.id)===String(id));if(!item||!item.series)return Promise.resolve();const season=Number(item.season)||1;const siblings=allItems.filter(x=>(x.series||"")===item.series&&(Number(x.season)||1)===season).sort((a,b)=>(Number(a.episode)||9999)-(Number(b.episode)||9999));const i=siblings.findIndex(x=>String(x.id)===String(id));const target=siblings[i+direction];if(!target)return Promise.resolve();const e=item.episode||i+1;item.episode=target.episode||i+2;target.episode=e;return Promise.all([save(item),save(target)])}
function getEpisodeStatusSummary(series){const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);return seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published").length,d=a.filter(x=>x.status==="draft").length,sch=a.filter(x=>x.status==="scheduled").length;return {season:s,label:a[0]?.seasonLabel||"Season "+s,total:a.length,published:p,drafts:d,scheduled:sch}})}
function renderSeasonAudience(series){const el=$("seasonCompare");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-audience"><b>SEASON AUDIENCE SNAPSHOT</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),published=a.filter(x=>x.status==="published"),views=published.reduce((n,x)=>n+(Number(x.viewCount)||0),0),avg=published.length?Math.round(views/published.length):0;return '<span>S'+s+' • '+published.length+' published • '+views.toLocaleString()+' total views • '+avg.toLocaleString()+' avg views/episode</span>'}).join("")+'</div>')}
function renderSeasonTopEpisodes(series){const el=$("seasonCompare");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-top-episodes"><b>TOP EPISODES BY VIEWS</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s).sort((p,q)=>(Number(q.viewCount)||0)-(Number(p.viewCount)||0)).slice(0,3);return '<span>S'+s+' • '+(a.length?a.map(x=>'EP '+(x.episode||"—")+' ('+(Number(x.viewCount)||0).toLocaleString()+' views)').join(' • '):'No episodes')+'</span>'}).join("")+'</div>')}
function renderSeasonEngagement(series){const el=$("seasonCompare");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-engagement"><b>SEASON ENGAGEMENT</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s);const views=a.reduce((n,x)=>n+(Number(x.viewCount)||0),0),likes=a.reduce((n,x)=>n+(Number(x.likes)||0),0),comments=a.reduce((n,x)=>n+(Number(x.comments)||0),0),recaws=a.reduce((n,x)=>n+(Number(x.recaws)||0),0),rate=views?((likes+comments+recaws)/views*100).toFixed(1):"0.0";return '<span>S'+s+' • '+views.toLocaleString()+' views • '+likes.toLocaleString()+' likes • '+comments.toLocaleString()+' comments • '+recaws.toLocaleString()+' re-caws • '+rate+'% interaction</span>'}).join("")+'</div>')}
function renderSeasonRuntime(series){const el=$("seasonCompare");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-runtime"><b>SEASON RUNTIME</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s);const secs=a.reduce((n,x)=>n+(Number(x.duration)||0),0);const avg=a.length?Math.round(secs/a.length):0;const fmt=n=>{n=Math.max(0,Math.round(n));const m=Math.floor(n/60),q=n%60;return m+'m '+q+'s'};return '<span>S'+s+' • '+a.length+' episodes • '+fmt(secs)+' total • '+fmt(avg)+' average</span>'}).join("")+'</div>')}
function renderSeasonCompare(series){const el=$("seasonCompare");if(!el)return;if(series==="all"){el.innerHTML="";return}const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.innerHTML=seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),v=a.reduce((n,x)=>n+(Number(x.viewCount)||0),0),l=a.reduce((n,x)=>n+(Number(x.likeCount)||0),0),c=a.reduce((n,x)=>n+(Number(x.commentCount)||0),0);return '<div class="season-compare-row"><b>'+esc(a[0]?.seasonLabel||"Season "+s)+'</b><span>'+a.length+' eps</span><span>'+v.toLocaleString()+' views</span><span>'+l.toLocaleString()+' likes</span><span>'+c.toLocaleString()+' comments</span></div>'}).join("")}
function renderSeasonLaunch(series){const el=$("seasonMilestones");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const now=Date.now();el.insertAdjacentHTML("afterbegin",'<div class="season-launch"><b>NEXT RELEASE</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s&&x.status==="scheduled"&&x.scheduledAt&&new Date(x.scheduledAt).getTime()>now).sort((x,y)=>new Date(x.scheduledAt)-new Date(y.scheduledAt));const x=a[0];return x?'<span>S'+s+' • EP '+(x.episode||"—")+' • '+new Date(x.scheduledAt).toLocaleString()+'</span>':'<span>S'+s+' • No upcoming release scheduled</span>'}).join("")+'</div>')}
function renderSeasonTargets(series){const el=$("seasonMilestones");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-targets"><b>SEASON TARGETS</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published").length;return '<span><strong>S'+s+'</strong> '+p+'/'+a.length+' released</span>'}).join("")+'</div>')}
function renderSeasonOrderHealth(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-order-health"><b>EPISODE ORDER HEALTH</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s).sort((p,q)=>(Number(p.episode)||0)-(Number(q.episode)||0));const nums=a.map(x=>Number(x.episode)).filter(Number.isFinite);const dup=nums.filter((n,i)=>nums.indexOf(n)!==i);const missing=[];for(let n=1;n<=(nums.length?Math.max(...nums):0);n++)if(!nums.includes(n))missing.push(n);const issue=dup.length||missing.length;return '<span>S'+s+' • '+(issue?'CHECK ORDER'+(missing.length?' • Missing '+missing.join(", "):"")+(dup.length?' • Duplicate '+[...new Set(dup)].join(", "):""):'Order OK')+'</span>'}).join("")+'</div>')}
function renderSeasonArchive(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-archive"><b>SEASON ARCHIVE STATUS</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),published=a.filter(x=>x.status==="published").length,total=a.length,views=a.reduce((n,x)=>n+(Number(x.viewCount)||0),0);return '<span>S'+s+' • '+published+'/'+total+' published • '+views.toLocaleString()+' views • '+(total&&published===total?'ARCHIVED':'IN PRODUCTION')+'</span>'}).join("")+'</div>')}
function renderSeriesTimelineStats(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const published=items.filter(x=>x.status==="published"),scheduled=items.filter(x=>x.status==="scheduled"),drafts=items.filter(x=>x.status==="draft");const views=published.reduce((n,x)=>n+(Number(x.viewCount)||0),0),likes=published.reduce((n,x)=>n+(Number(x.likes)||0),0);const avg=published.length?Math.round(views/published.length):0;el.insertAdjacentHTML("afterbegin",'<div class="series-timeline-stats"><b>RELEASE SNAPSHOT</b><span>'+published.length+' live • '+scheduled.length+' scheduled • '+drafts.length+' drafts • '+views.toLocaleString()+' views • '+avg.toLocaleString()+' avg views • '+likes.toLocaleString()+' likes</span></div>')}
function renderSeasonEpisodeMap(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-episode-map"><b>SEASON EPISODE MAP</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s).sort((p,q)=>(Number(p.episode)||0)-(Number(q.episode)||0));return '<span>S'+s+' • '+(a.length?a.map(x=>'EP '+(x.episode||"—")+' '+(x.status==="published"?'●':'○')).join('  '):'No episodes')+'</span>'}).join("")+'</div>')}
function renderSeasonReleaseQueue(series){const el=$("seriesTimeline");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));const queue=items.filter(x=>x.status!=="published").slice(0,8);el.insertAdjacentHTML("afterbegin",'<div class="season-release-queue"><b>RELEASE QUEUE</b>'+(queue.length?queue.map(x=>'<span>S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+(x.status||"draft").toUpperCase()+'</span>').join(""):'<span>No unreleased episodes in the current series.</span>')+'</div>')}
function renderSeasonCompletionChecklist(series){const el=$("seasonMilestones");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-completion-checklist"><b>SEASON COMPLETION CHECKLIST</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),published=a.filter(x=>x.status==="published").length,scheduled=a.filter(x=>x.status==="scheduled").length,ready=a.filter(x=>String(x.caption||"").trim()&&(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl)).length;const checks=[published===a.length&&a.length>0,scheduled===0,ready===a.length];return '<span>S'+s+' • '+(checks.filter(Boolean).length)+'/3 checks complete — '+published+'/'+a.length+' published • '+scheduled+' scheduled • '+ready+'/'+a.length+' ready</span>'}).join("")+'</div>')}
function renderSeasonMilestones(series){const el=$("seasonMilestones");if(!el||series==="all"){if(el)el.innerHTML="";return}const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.innerHTML='<div class="milestone-title">SEASON MILESTONES</div>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),p=a.filter(x=>x.status==="published"),views=p.reduce((n,x)=>n+(Number(x.viewCount)||0),0);const milestones=[a.length>=1?"FIRST EPISODE":null,a.length>=5?"5 EPISODES":null,a.length>=10?"10 EPISODES":null,p.length===a.length&&a.length?"FULL SEASON RELEASED":null,views>=1000?"1K VIEWS":null].filter(Boolean);return '<div class="milestone-season"><b>'+esc(a[0]?.seasonLabel||"Season "+s)+'</b><div>'+milestones.map(m=>'<span>✓ '+m+'</span>').join("")+'</div></div>'}).join("")}
function renderSeasonReadiness(series){const el=$("seasonPlanner");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const out=seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),published=a.filter(x=>x.status==="published").length,scheduled=a.filter(x=>x.status==="scheduled").length,drafts=a.filter(x=>x.status==="draft").length;return {s,total:a.length,published,scheduled,drafts}});el.insertAdjacentHTML("afterbegin",'<div class="readiness-grid">'+out.map(r=>'<div class="readiness-card"><b>S'+r.s+'</b><span>'+r.published+'/'+r.total+' released</span><small>'+r.scheduled+' scheduled • '+r.drafts+' drafts</small></div>').join("")+'</div>')}
function renderProductionGaps(series){const el=$("seasonPlanner");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);const gaps=[];seasons.forEach(s=>{const a=items.filter(x=>(Number(x.season)||1)===s);const nums=a.map(x=>Number(x.episode)).filter(Number.isFinite);if(nums.length){for(let n=1;n<=Math.max(...nums);n++)if(!nums.includes(n))gaps.push("S"+s+" EP "+n)}});el.insertAdjacentHTML("afterbegin",'<div class="production-gaps"><b>PRODUCTION GAPS</b><span>'+(gaps.length?gaps.join(" • "):"No episode-number gaps detected")+'</span></div>')}
function renderEpisodeReadiness(series){const el=$("seasonPlanner");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));el.insertAdjacentHTML("afterbegin",'<div class="episode-readiness"><div class="mini-title">EPISODE READINESS</div>'+items.map(x=>{const checks=[["VIDEO",!!(x.videoUrl||x.videoBlob)],["CAPTION",!!String(x.caption||"").trim()],["THUMBNAIL",!!(x.thumbUrl||x.thumbnailUrl)],["CREATOR",!!String(x.creator||"").trim()],["METADATA",!!(x.series&&x.season&&x.episode)]];const missing=checks.filter(c=>!c[1]).map(c=>c[0]);return '<div class="readiness-episode"><b>S'+(x.season||1)+' • EP '+(x.episode||"—")+'</b><span class="'+(missing.length?'needs':'ready')+'">'+(missing.length?'NEEDS '+missing.join(' • '):'READY')+'</span></div>'}).join("")+'</div>')}
function renderSeasonMissingAssets(series){const el=$("seasonPlanner");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||0)-(Number(b.episode)||0));const missing=items.flatMap(x=>{const m=[];if(!(x.videoUrl||x.videoBlob))m.push("VIDEO");if(!(x.thumbUrl||x.thumbnailUrl))m.push("THUMB");if(!String(x.caption||"").trim())m.push("CAPTION");return m.length?[{x,m}]:[]});el.insertAdjacentHTML("afterbegin",'<div class="season-missing-assets"><b>MISSING ASSETS</b>'+(missing.length?missing.map(({x,m})=>'<span>S'+(x.season||1)+' • EP '+(x.episode||"—")+' — '+m.join(" • ")+'</span>').join(""):'<span>All episodes have the core assets required for production.</span>')+'</div>')}
function renderSeasonPlanner(series){const el=$("seasonPlanner");if(!el||series==="all"){if(el)el.innerHTML="";return}const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.innerHTML='<div class="planner-title">PRODUCTION PLANNER</div>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s).sort((x,y)=>(Number(x.episode)||9999)-(Number(y.episode)||9999));return '<div class="planner-season"><b>'+esc(a[0]?.seasonLabel||"Season "+s)+'</b>'+a.map(x=>'<div class="planner-episode"><span>EP '+(x.episode||"—")+'</span><em class="'+x.status+'">'+x.status+'</em><small>'+esc(x.caption||"Untitled Caw")+'</small></div>').join("")+'</div>'}).join("")}
function renderSeasonPublishGate(series){const el=$("seasonHealth");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="season-publish-gate"><b>PUBLISH GATE</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),missing=a.filter(x=>!(x.videoUrl||x.videoBlob)||!(x.thumbUrl||x.thumbnailUrl)||!String(x.caption||"").trim()),drafts=a.filter(x=>x.status==="draft"),scheduled=a.filter(x=>x.status==="scheduled");const ready=a.length>0&&!missing.length&&!drafts.length&&!scheduled.length&&a.every(x=>x.status==="published");return '<span>S'+s+' • '+(ready?'READY TO CLOSE SEASON':'NOT READY')+' — '+(missing.length?'Assets '+missing.length+' • ':'')+(drafts.length?'Drafts '+drafts.length+' • ':'')+(scheduled.length?'Scheduled '+scheduled.length:'')+'</span>'}).join("")+'</div>')}
function renderSeasonHealthBreakdown(series){const el=$("seasonHealth");if(!el||series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);el.insertAdjacentHTML("afterbegin",'<div class="health-breakdown"><b>SEASON HEALTH BREAKDOWN</b>'+seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s);const published=a.filter(x=>x.status==="published").length,draft=a.filter(x=>x.status==="draft").length,scheduled=a.filter(x=>x.status==="scheduled").length;const ready=a.filter(x=>String(x.caption||"").trim()&&(x.videoUrl||x.videoBlob)&&(x.thumbUrl||x.thumbnailUrl)).length;return '<span>S'+s+' • '+published+' published • '+scheduled+' scheduled • '+draft+' drafts • '+ready+'/'+a.length+' production-ready</span>'}).join("")+'</div>')}
function renderSeasonHealth(series){const el=$("seasonCompare");if(!el||series==="all")return;const rows=getEpisodeStatusSummary(series);el.insertAdjacentHTML("afterbegin",rows.map(r=>{const ready=r.total&&r.published===r.total,attention=r.drafts>0||r.scheduled>0;return '<div class="season-health '+(ready?'ready':'')+'"><b>'+esc(r.label)+'</b><span>'+(ready?'READY • Full season released':attention?(r.scheduled+' scheduled • '+r.drafts+' drafts'):'Needs episodes')+'</span></div>'}).join(""))}
function renderSeasonProgress(series){const el=$("seasonCompare");if(!el||series==="all")return;const rows=getEpisodeStatusSummary(series);el.insertAdjacentHTML("afterbegin",rows.map(r=>{const pct=r.total?Math.round(r.published/r.total*100):0;return '<div class="season-progress"><div><b>'+esc(r.label)+'</b><span>'+pct+'% released</span></div><div class="progress-track"><i style="width:'+pct+'%"></i></div></div>'}).join(""))}
function renderSeasonStats(series){const el=$("timelineTracks");if(series==="all")return;const items=allItems.filter(x=>(x.series||"")===series);const seasons=[...new Set(items.map(x=>Number(x.season)||1))].sort((a,b)=>a-b);$("timelineTitle").textContent=series+" • "+items.length+" episodes";el.insertAdjacentHTML("beforeend",`<div class="season-stats">${seasons.map(s=>{const a=items.filter(x=>(Number(x.season)||1)===s),v=a.reduce((n,x)=>n+(Number(x.viewCount)||0),0);return `<span><b>${esc(a[0]?.seasonLabel||"Season "+s)}</b> · ${a.length} episodes · ${v.toLocaleString()} views</span>`}).join("")}</div>`)}
function renderSeriesTimeline(){const series=$("studioSeries").value;if(series==="all"){$("timelineTitle").textContent="Select a series";$("timelineTracks").innerHTML="<span class=\"timeline-empty\">Choose a series above to view its episode timeline.</span>";$("renumberSeasonBtn").hidden=true;return}const items=allItems.filter(x=>(x.series||"")===series).sort((a,b)=>(Number(a.season)||1)-(Number(b.season)||1)||(Number(a.episode)||9999)-(Number(b.episode)||9999));$("timelineTitle").textContent=series;const seasons=[...new Set(items.map(x=>Number(x.season)||1))];$("renumberSeasonBtn").hidden=!seasons.length;$("renumberSeasonBtn").onclick=async()=>{const season=Number(prompt("Renumber which season?",String(seasons[0]||1)));if(!Number.isFinite(season)||season<1)return;await renumberSeriesSeason(series,season);allItems=await getAll();refresh()};$("timelineTracks").innerHTML=seasons.map(season=>`<div class="timeline-season"><b>SEASON ${season}</b><button type="button" class="season-edit" data-season="${season}">Edit Season</button><div>${items.filter(x=>(Number(x.season)||1)===season).map(x=>`<div class="timeline-card"><button class="timeline-episode" data-series-id="${x.id}"><strong>EP ${x.episode||"—"}</strong><span>${esc(x.caption||"Untitled Caw")}</span><i class="${x.status}">${x.status}</i></button><div class="timeline-arrows"><button type="button" data-move="-1" data-id="${x.id}">↑</button><button type="button" data-move="1" data-id="${x.id}">↓</button></div></div>`).join("")}</div></div>`).join("");document.querySelectorAll("[data-series-id]").forEach(b=>b.onclick=()=>{const x=allItems.find(v=>String(v.id)===b.dataset.seriesId);if(x)openEditor(x)})}
function renderCalendar(){const list=allItems.filter(x=>x.status==="scheduled"&&x.scheduledAt).sort((a,b)=>new Date(a.scheduledAt)-new Date(b.scheduledAt));const next=list[0];$("nextScheduled").textContent=next?`${esc(next.caption||"Untitled Caw")} • ${new Date(next.scheduledAt).toLocaleString()}`:"No scheduled Caws";$("scheduleList").innerHTML=list.slice(0,6).map(x=>`<div class="schedule-item"><span>${new Date(x.scheduledAt).toLocaleDateString()}</span><b>${esc(x.caption||"Untitled Caw")}</b><small>${new Date(x.scheduledAt).toLocaleTimeString([], {hour:"numeric",minute:"2-digit"})}</small></div>`).join("")}
function updateSelection(){const n=selected.size;$("selectionCount").textContent=n+" selected";$("bulkLabel").textContent=n+" Caw"+(n===1?"":"s")+" selected";$("bulkBar").classList.toggle("show",n>0)}
function refreshSeriesFilter(){const sel=$("studioSeries"),current=sel.value,names=[...new Set(allItems.map(x=>(x.series||"").trim()).filter(Boolean))].sort();sel.innerHTML=`<option value="all">All Series</option>`+names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join("");if(names.includes(current))sel.value=current}
function renderLibrary(){const q=$("studioSearch").value.trim().toLowerCase(),cat=$("studioCategory").value,series=$("studioSeries").value;let list=allItems.filter(x=>(currentTab==="all"||x.status===currentTab)&&(cat==="all"||(x.category||"General")==cat)&&(series==="all"||(x.series||"")===series));if(q)list=list.filter(x=>(x.caption+" "+x.creator+" "+x.handle).toLowerCase().includes(q));const sort=$("studioSort").value;if(sort==="views")list.sort((a,b)=>(b.views||0)-(a.views||0));if(sort==="likes")list.sort((a,b)=>(b.likes||0)-(a.likes||0));if(sort==="engagement")list.sort((a,b)=>(((b.likes||0)+(b.comments||0)+(b.recasts||0))/Math.max(b.views||0,1))-(((a.likes||0)+(a.comments||0)+(a.recasts||0))/Math.max(a.views||0,1)));$("studioLibrary").innerHTML=list.length?list.map(card).join(""):`<section class="card panel empty-studio"><div class="panel-title">NOTHING HERE YET</div><h3>Create your first Caw.</h3><p>Your drafts and published Caws will appear here.</p><button class="post-button" onclick="document.getElementById('createCaw').click()">＋ Create Caw</button></section>`;document.querySelectorAll("[data-select-id]").forEach(cb=>cb.onchange=()=>{const id=Number(cb.dataset.selectId);cb.checked?selected.add(id):selected.delete(id);updateSelection()});document.querySelectorAll(".studio-item button").forEach(b=>b.onclick=async()=>{const x=allItems.find(x=>String(x.id)===b.dataset.id);if(!x)return;if(b.dataset.act==="edit")openEditor(x);if(b.dataset.act==="duplicate")duplicateCaw(x.id);if(b.dataset.act==="publish")quickStatus(x.id,"published");if(b.dataset.act==="unpublish")quickStatus(x.id,"draft");if(b.dataset.act==="analytics"){showAnalytics(x);return}if(b.dataset.act==="view"){localStorage.setItem("crowspace:cawFocus",String(x.id));location.href="caws.html#caw-"+x.id}if(b.dataset.act==="delete"&&confirm("Delete this Caw?")){await remove(x.id);refresh()}})}
$("selectAllCaws").onclick=()=>{document.querySelectorAll("[data-select-id]").forEach(cb=>{selected.add(Number(cb.dataset.selectId));cb.checked=true});updateSelection()};$("clearSelection").onclick=()=>{selected.clear();renderLibrary()};async function bulkStatus(status){for(const id of [...selected]){const x=allItems.find(v=>v.id===id);if(x&&(status!=="published"||String(x.caption||"").trim()))await save({...x,status})}selected.clear();await refresh()}$("bulkPublish").onclick=()=>bulkStatus("published");$("bulkDraft").onclick=()=>bulkStatus("draft");$("bulkDelete").onclick=async()=>{if(!confirm("Delete selected Caws?"))return;for(const id of [...selected])await remove(id);selected.clear();await refresh()};
$("closeAnalytics").onclick=()=>document.getElementById("analyticsModal").classList.remove("show");document.getElementById("analyticsModal").addEventListener("click",e=>{if(e.target.id==="analyticsModal")e.currentTarget.classList.remove("show")});document.getElementById("studioSort").onchange=renderLibrary;
updateSelection();document.querySelectorAll(".studio-tabs button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".studio-tabs button").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");currentTab=b.dataset.tab;renderLibrary()});$("studioSearch").oninput=renderLibrary;$("studioCategory").onchange=renderLibrary;$("studioSeries").onchange=()=>{renderLibrary();renderSeriesTimeline()};
document.addEventListener("click",async e=>{const seasonBtn=e.target.closest(".season-edit");if(seasonBtn){const season=Number(seasonBtn.dataset.season);const seriesName=seasonBtn.dataset.series||$("studioSeries")?.value||"";if(!seriesName||seriesName==="all")return;const title=prompt("Season label (optional):",`Season ${season}`);if(title===null)return;if(typeof updateSeriesMeta==="function")await updateSeriesMeta(seriesName,season,{seasonLabel:title.trim()||`Season ${season}`});allItems=await all();refresh();return}const moveBtn=e.target.closest("[data-move]");if(moveBtn){const id=moveBtn.dataset.id,delta=Number(moveBtn.dataset.move);if(typeof moveEpisode==="function")await moveEpisode(id,delta);allItems=await all();refresh()}});
initDB().then(()=>refresh()).catch(e=>{console.error("[CrowSpace Studio]",e);const statusEl=$("studioStatus");if(statusEl)statusEl.textContent="Creator Studio could not initialize. Refresh and try again.";});
